# Initially generated by GitHub Copilot.
import unittest

from mb_diff_mpu.mpplus_file_matching import matched_plus_file_pairs


class TestMatchedPlusFilePairs(unittest.TestCase):
    def test_provenance_sidecar_is_ignored(self):
        old_files = ["A2-Exodus.json", "provenance.md", "A1-Genesis.json"]
        new_files = ["provenance.md", "A1-Genesis.json", "A2-Exodus.json"]

        pairs = matched_plus_file_pairs(old_files, new_files)

        self.assertEqual(
            pairs,
            [
                ("A1-Genesis", "A1-Genesis.json", "A1-Genesis.json"),
                ("A2-Exodus", "A2-Exodus.json", "A2-Exodus.json"),
            ],
        )

    def test_unexpected_non_json_old_files_raises(self):
        with self.assertRaisesRegex(
            ValueError,
            r"Unexpected non-JSON plus/ filename\(s\) in old_files: vendoring\.md",
        ):
            matched_plus_file_pairs(
                ["A1-Genesis.json", "vendoring.md"],
                ["A1-Genesis.json", "provenance.md"],
            )

    def test_unexpected_non_json_new_files_raises(self):
        with self.assertRaisesRegex(
            ValueError,
            r"Unexpected non-JSON plus/ filename\(s\) in new_files: vendoring\.md",
        ):
            matched_plus_file_pairs(
                ["A1-Genesis.json", "provenance.md"],
                ["A1-Genesis.json", "vendoring.md"],
            )


if __name__ == "__main__":
    unittest.main()
